     1→import * as Sentry from '@sentry/react';
     2→
     3→export function initSentry() {
     4→  // Only initialize in production or staging
     5→  if (import.meta.env.PROD && import.meta.env.VITE_SENTRY_DSN) {
     6→    Sentry.init({
     7→      dsn: import.meta.env.VITE_SENTRY_DSN,
     8→      environment: import.meta.env.VITE_ENVIRONMENT || 'production',
     9→
    10→      // Performance monitoring
    11→      tracesSampleRate: 0.1, // 10% of transactions
    12→
    13→      // Only send errors, not all events
    14→      beforeSend(event) {
    15→        // Don't send events in development
    16→        if (import.meta.env.DEV) {
    17→          return null;
    18→        }
    19→        return event;
    20→      },
    21→
    22→      // Integrations
    23→      integrations: [
    24→        Sentry.browserTracingIntegration(),
    25→        Sentry.replayIntegration({
    26→          // Only capture replays on errors
    27→          maskAllText: true,
    28→          blockAllMedia: true,
    29→        }),
    30→      ],
    31→
    32→      // Session replay - only on errors
    33→      replaysSessionSampleRate: 0,
    34→      replaysOnErrorSampleRate: 1.0, // 100% of errors get replay
    35→    });
    36→  }
    37→}
    38→
    39→// Re-export Sentry for use in error boundaries
    40→export { Sentry };
    41→

